    pub(crate) fn compare_root_sw_composition_prototype(
        &self,
        other: &Document,
        a: &RootSwCompositionPrototype,
        b: &RootSwCompositionPrototype,
        path: &str,
    ) -> Result<(), String> {
        self.compare_atp_prototype(other, a.base(), b.base(), path)?;
        self.compare_variation_point_capable(
            other,
            a.variation_point_capable(),
            b.variation_point_capable(),
            path,
        )?;
        let list_a = a.get_calibration_parameter_value_set_refs();
        let list_b = b.get_calibration_parameter_value_set_refs();
        if list_a.len() != list_b.len() {
            return Err(format!(
                "{path}: CALIBRATION_PARAMETER_VALUE_SET_REFS length mismatch"
            ));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            let x = self.ref_types.get(*x).ok_or_else(|| format!("{path}.CALIBRATION_PARAMETER_VALUE_SET_REFS[{index}]: id not found in own arena"))?;
            let y = other.ref_types.get(*y).ok_or_else(|| format!("{path}.CALIBRATION_PARAMETER_VALUE_SET_REFS[{index}]: id not found in other arena"))?;
            self.compare_ref_type(
                other,
                x,
                y,
                &format!("{path}.CALIBRATION_PARAMETER_VALUE_SET_REFS[{index}]"),
            )?;
        }
        if a.get_flat_map_ref() != b.get_flat_map_ref() {
            return Err(format!("{path}: FLAT_MAP_REF mismatch"));
        }
        if a.get_software_composition_t_ref() != b.get_software_composition_t_ref() {
            return Err(format!("{path}: SOFTWARE_COMPOSITION_T_REF mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_system(
        &self,
        other: &Document,
        a: &System,
        b: &System,
        path: &str,
    ) -> Result<(), String> {
        self.compare_atp_structure_element(other, a.base(), b.base(), path)?;
        let list_a = a.get_client_id_definition_set_refs();
        let list_b = b.get_client_id_definition_set_refs();
        if list_a.len() != list_b.len() {
            return Err(format!(
                "{path}: CLIENT_ID_DEFINITION_SET_REFS length mismatch"
            ));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            let x = self.ref_types.get(*x).ok_or_else(|| {
                format!("{path}.CLIENT_ID_DEFINITION_SET_REFS[{index}]: id not found in own arena")
            })?;
            let y = other.ref_types.get(*y).ok_or_else(|| {
                format!(
                    "{path}.CLIENT_ID_DEFINITION_SET_REFS[{index}]: id not found in other arena"
                )
            })?;
            self.compare_ref_type(
                other,
                x,
                y,
                &format!("{path}.CLIENT_ID_DEFINITION_SET_REFS[{index}]"),
            )?;
        }
        if a.get_container_i_pdu_header_byte_order() != b.get_container_i_pdu_header_byte_order() {
            return Err(format!(
                "{path}: CONTAINER_I_PDU_HEADER_BYTE_ORDER mismatch"
            ));
        }
        if a.get_ecu_extract_version() != b.get_ecu_extract_version() {
            return Err(format!("{path}: ECU_EXTRACT_VERSION mismatch"));
        }
        let list_a = a.get_fibex_element_refs();
        let list_b = b.get_fibex_element_refs();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: FIBEX_ELEMENT_REFS length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            let x = self.ref_types.get(*x).ok_or_else(|| {
                format!("{path}.FIBEX_ELEMENT_REFS[{index}]: id not found in own arena")
            })?;
            let y = other.ref_types.get(*y).ok_or_else(|| {
                format!("{path}.FIBEX_ELEMENT_REFS[{index}]: id not found in other arena")
            })?;
            self.compare_ref_type(other, x, y, &format!("{path}.FIBEX_ELEMENT_REFS[{index}]"))?;
        }
        let list_a = a.get_interpolation_routine_mapping_set_refs();
        let list_b = b.get_interpolation_routine_mapping_set_refs();
        if list_a.len() != list_b.len() {
            return Err(format!(
                "{path}: INTERPOLATION_ROUTINE_MAPPING_SET_REFS length mismatch"
            ));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            let x = self.ref_types.get(*x).ok_or_else(|| format!("{path}.INTERPOLATION_ROUTINE_MAPPING_SET_REFS[{index}]: id not found in own arena"))?;
            let y = other.ref_types.get(*y).ok_or_else(|| format!("{path}.INTERPOLATION_ROUTINE_MAPPING_SET_REFS[{index}]: id not found in other arena"))?;
            self.compare_ref_type(
                other,
                x,
                y,
                &format!("{path}.INTERPOLATION_ROUTINE_MAPPING_SET_REFS[{index}]"),
            )?;
        }
        let list_a = a.get_j1939_shared_address_clusters();
        let list_b = b.get_j1939_shared_address_clusters();
        if list_a.len() != list_b.len() {
            return Err(format!(
                "{path}: J1939_SHARED_ADDRESS_CLUSTERS length mismatch"
            ));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            let x = self.j1939_shared_address_clusters.get(*x).ok_or_else(|| {
                format!("{path}.J1939_SHARED_ADDRESS_CLUSTERS[{index}]: id not found in own arena")
            })?;
            let y = other.j1939_shared_address_clusters.get(*y).ok_or_else(|| {
                format!(
                    "{path}.J1939_SHARED_ADDRESS_CLUSTERS[{index}]: id not found in other arena"
                )
            })?;
            self.compare_j1939_shared_address_cluster(
                other,
                x,
                y,
                &format!("{path}.J1939_SHARED_ADDRESS_CLUSTERS[{index}]"),
            )?;
        }
        let list_a = a.get_mappings();
        let list_b = b.get_mappings();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: MAPPINGS length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            let x = self
                .system_mappings
                .get(*x)
                .ok_or_else(|| format!("{path}.MAPPINGS[{index}]: id not found in own arena"))?;
            let y = other
                .system_mappings
                .get(*y)
                .ok_or_else(|| format!("{path}.MAPPINGS[{index}]: id not found in other arena"))?;
            self.compare_system_mapping(other, x, y, &format!("{path}.MAPPINGS[{index}]"))?;
        }
        if a.get_pnc_vector_length() != b.get_pnc_vector_length() {
            return Err(format!("{path}: PNC_VECTOR_LENGTH mismatch"));
        }
        if a.get_pnc_vector_offset() != b.get_pnc_vector_offset() {
            return Err(format!("{path}: PNC_VECTOR_OFFSET mismatch"));
        }
        if a.get_root_software_composition() != b.get_root_software_composition() {
            return Err(format!("{path}: ROOT_SOFTWARE_COMPOSITION mismatch"));
        }
        let list_a = a.get_sw_cluster_refs();
        let list_b = b.get_sw_cluster_refs();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: SW_CLUSTER_REFS length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            let x = self.ref_types.get(*x).ok_or_else(|| {
                format!("{path}.SW_CLUSTER_REFS[{index}]: id not found in own arena")
            })?;
            let y = other.ref_types.get(*y).ok_or_else(|| {
                format!("{path}.SW_CLUSTER_REFS[{index}]: id not found in other arena")
            })?;
            self.compare_ref_type(other, x, y, &format!("{path}.SW_CLUSTER_REFS[{index}]"))?;
        }
        let list_a = a.get_system_documentations();
        let list_b = b.get_system_documentations();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: SYSTEM_DOCUMENTATIONS length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            let x = self.chapters.get(*x).ok_or_else(|| {
                format!("{path}.SYSTEM_DOCUMENTATIONS[{index}]: id not found in own arena")
            })?;
            let y = other.chapters.get(*y).ok_or_else(|| {
                format!("{path}.SYSTEM_DOCUMENTATIONS[{index}]: id not found in other arena")
            })?;
            self.compare_chapter(
                other,
                x,
                y,
                &format!("{path}.SYSTEM_DOCUMENTATIONS[{index}]"),
            )?;
        }
        if a.get_system_version() != b.get_system_version() {
            return Err(format!("{path}: SYSTEM_VERSION mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_system_mapping(
        &self,
        other: &Document,
        a: &SystemMapping,
        b: &SystemMapping,
        path: &str,
    ) -> Result<(), String> {
        self.compare_identifiable(other, a.base(), b.base(), path)?;
        self.compare_variation_point_capable(
            other,
            a.variation_point_capable(),
            b.variation_point_capable(),
            path,
        )?;
        let list_a = a.get_application_partition_to_ecu_partition_mappings();
        let list_b = b.get_application_partition_to_ecu_partition_mappings();
        if list_a.len() != list_b.len() {
            return Err(format!(
                "{path}: APPLICATION_PARTITION_TO_ECU_PARTITION_MAPPINGS length mismatch"
            ));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            let x = self.application_partition_to_ecu_partition_mappings.get(*x).ok_or_else(|| format!("{path}.APPLICATION_PARTITION_TO_ECU_PARTITION_MAPPINGS[{index}]: id not found in own arena"))?;
            let y = other.application_partition_to_ecu_partition_mappings.get(*y).ok_or_else(|| format!("{path}.APPLICATION_PARTITION_TO_ECU_PARTITION_MAPPINGS[{index}]: id not found in other arena"))?;
            self.compare_application_partition_to_ecu_partition_mapping(
                other,
                x,
                y,
                &format!("{path}.APPLICATION_PARTITION_TO_ECU_PARTITION_MAPPINGS[{index}]"),
            )?;
        }
        let list_a = a.get_app_os_task_proxy_to_ecu_task_proxy_mappings();
        let list_b = b.get_app_os_task_proxy_to_ecu_task_proxy_mappings();
        if list_a.len() != list_b.len() {
            return Err(format!(
                "{path}: APP_OS_TASK_PROXY_TO_ECU_TASK_PROXY_MAPPINGS length mismatch"
            ));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            let x = self.app_os_task_proxy_to_ecu_task_proxy_mappings.get(*x).ok_or_else(|| format!("{path}.APP_OS_TASK_PROXY_TO_ECU_TASK_PROXY_MAPPINGS[{index}]: id not found in own arena"))?;
            let y = other.app_os_task_proxy_to_ecu_task_proxy_mappings.get(*y).ok_or_else(|| format!("{path}.APP_OS_TASK_PROXY_TO_ECU_TASK_PROXY_MAPPINGS[{index}]: id not found in other arena"))?;
            self.compare_app_os_task_proxy_to_ecu_task_proxy_mapping(
                other,
                x,
                y,
                &format!("{path}.APP_OS_TASK_PROXY_TO_ECU_TASK_PROXY_MAPPINGS[{index}]"),
            )?;
        }
        let list_a = a.get_com_management_mappings();
        let list_b = b.get_com_management_mappings();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: COM_MANAGEMENT_MAPPINGS length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            let x = self.com_management_mappings.get(*x).ok_or_else(|| {
                format!("{path}.COM_MANAGEMENT_MAPPINGS[{index}]: id not found in own arena")
            })?;
            let y = other.com_management_mappings.get(*y).ok_or_else(|| {
                format!("{path}.COM_MANAGEMENT_MAPPINGS[{index}]: id not found in other arena")
            })?;
            self.compare_com_management_mapping(
                other,
                x,
                y,
                &format!("{path}.COM_MANAGEMENT_MAPPINGS[{index}]"),
            )?;
        }
        let list_a = a.get_crypto_service_mappings();
        let list_b = b.get_crypto_service_mappings();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: CRYPTO_SERVICE_MAPPINGS length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            if x != y {
                return Err(format!("{path}.CRYPTO_SERVICE_MAPPINGS[{index}] mismatch"));
            }
        }
        let list_a = a.get_data_mappings();
        let list_b = b.get_data_mappings();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: DATA_MAPPINGS length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            if x != y {
                return Err(format!("{path}.DATA_MAPPINGS[{index}] mismatch"));
            }
        }
        if a.get_dds_i_signal_to_topic_mappings() != b.get_dds_i_signal_to_topic_mappings() {
            return Err(format!("{path}: DDS_I_SIGNAL_TO_TOPIC_MAPPINGS mismatch"));
        }
        let list_a = a.get_ecu_resource_mappings();
        let list_b = b.get_ecu_resource_mappings();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: ECU_RESOURCE_MAPPINGS length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            let x = self.ecu_mappings.get(*x).ok_or_else(|| {
                format!("{path}.ECU_RESOURCE_MAPPINGS[{index}]: id not found in own arena")
            })?;
            let y = other.ecu_mappings.get(*y).ok_or_else(|| {
                format!("{path}.ECU_RESOURCE_MAPPINGS[{index}]: id not found in other arena")
            })?;
            self.compare_ecu_mapping(
                other,
                x,
                y,
                &format!("{path}.ECU_RESOURCE_MAPPINGS[{index}]"),
            )?;
        }
        if a.get_j1939_controller_application_to_j1939_nm_node_mappings()
            != b.get_j1939_controller_application_to_j1939_nm_node_mappings()
        {
            return Err(format!(
                "{path}: J1939_CONTROLLER_APPLICATION_TO_J1939_NM_NODE_MAPPINGS mismatch"
            ));
        }
        if a.get_mapping_constraints() != b.get_mapping_constraints() {
            return Err(format!("{path}: MAPPING_CONSTRAINTS mismatch"));
        }
        if a.get_pnc_mappings() != b.get_pnc_mappings() {
            return Err(format!("{path}: PNC_MAPPINGS mismatch"));
        }
        if a.get_port_element_to_com_resource_mappings()
            != b.get_port_element_to_com_resource_mappings()
        {
            return Err(format!(
                "{path}: PORT_ELEMENT_TO_COM_RESOURCE_MAPPINGS mismatch"
            ));
        }
        if a.get_resource_estimations() != b.get_resource_estimations() {
            return Err(format!("{path}: RESOURCE_ESTIMATIONS mismatch"));
        }
        if a.get_resource_to_application_partition_mappings()
            != b.get_resource_to_application_partition_mappings()
        {
            return Err(format!(
                "{path}: RESOURCE_TO_APPLICATION_PARTITION_MAPPINGS mismatch"
            ));
        }
        if a.get_rte_event_separations() != b.get_rte_event_separations() {
            return Err(format!("{path}: RTE_EVENT_SEPARATIONS mismatch"));
        }
        if a.get_rte_event_to_os_task_proxy_mappings()
            != b.get_rte_event_to_os_task_proxy_mappings()
        {
            return Err(format!(
                "{path}: RTE_EVENT_TO_OS_TASK_PROXY_MAPPINGS mismatch"
            ));
        }
        if a.get_signal_path_constraints() != b.get_signal_path_constraints() {
            return Err(format!("{path}: SIGNAL_PATH_CONSTRAINTS mismatch"));
        }
        if a.get_software_cluster_to_application_partition_mappings()
            != b.get_software_cluster_to_application_partition_mappings()
        {
            return Err(format!(
                "{path}: SOFTWARE_CLUSTER_TO_APPLICATION_PARTITION_MAPPINGS mismatch"
            ));
        }
        if a.get_software_cluster_to_resource_mappings()
            != b.get_software_cluster_to_resource_mappings()
        {
            return Err(format!(
                "{path}: SOFTWARE_CLUSTER_TO_RESOURCE_MAPPINGS mismatch"
            ));
        }
        if a.get_sw_cluster_mappings() != b.get_sw_cluster_mappings() {
            return Err(format!("{path}: SW_CLUSTER_MAPPINGS mismatch"));
        }
        if a.get_swc_to_application_partition_mappings()
            != b.get_swc_to_application_partition_mappings()
        {
            return Err(format!(
                "{path}: SWC_TO_APPLICATION_PARTITION_MAPPINGS mismatch"
            ));
        }
        let list_a = a.get_sw_impl_mappings();
        let list_b = b.get_sw_impl_mappings();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: SW_IMPL_MAPPINGS length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            let x = self.swc_to_impl_mappings.get(*x).ok_or_else(|| {
                format!("{path}.SW_IMPL_MAPPINGS[{index}]: id not found in own arena")
            })?;
            let y = other.swc_to_impl_mappings.get(*y).ok_or_else(|| {
                format!("{path}.SW_IMPL_MAPPINGS[{index}]: id not found in other arena")
            })?;
            self.compare_swc_to_impl_mapping(
                other,
                x,
                y,
                &format!("{path}.SW_IMPL_MAPPINGS[{index}]"),
            )?;
        }
        let list_a = a.get_sw_mappings();
        let list_b = b.get_sw_mappings();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: SW_MAPPINGS length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            let x = self
                .swc_to_ecu_mappings
                .get(*x)
                .ok_or_else(|| format!("{path}.SW_MAPPINGS[{index}]: id not found in own arena"))?;
            let y = other.swc_to_ecu_mappings.get(*y).ok_or_else(|| {
                format!("{path}.SW_MAPPINGS[{index}]: id not found in other arena")
            })?;
            self.compare_swc_to_ecu_mapping(other, x, y, &format!("{path}.SW_MAPPINGS[{index}]"))?;
        }
        if a.get_system_signal_group_to_com_resource_mappings()
            != b.get_system_signal_group_to_com_resource_mappings()
        {
            return Err(format!(
                "{path}: SYSTEM_SIGNAL_GROUP_TO_COM_RESOURCE_MAPPINGS mismatch"
            ));
        }
        if a.get_system_signal_to_com_resource_mappings()
            != b.get_system_signal_to_com_resource_mappings()
        {
            return Err(format!(
                "{path}: SYSTEM_SIGNAL_TO_COM_RESOURCE_MAPPINGS mismatch"
            ));
        }
        Ok(())
    }
